const userArrow = {
  name: "Basia",
  greet: () => {
    console.log(this); // this arrow function = this z ZEWNATRZ obiektu, NIE userArrow!
  },
};

userArrow.greet(); // this !== userArrow (undefined w module ES)

const userArrow = {
  name: "Basia",
  greetCorrect() {
    // Zwykla metoda MA WLASNE this (= userArrow)
    const inner = () => {
      console.log(`Czesc, jestem ${this.name}`); // this === userArrow (dziedziczone)
    };
    inner();
  },
};

userArrow.greetCorrect(); // "Czesc, jestem Basia"

const timer = {
  sekundy: 0,
  startZlyThis() {
    setTimeout(function () {
      // ZWYKLA funkcja jako callback - this TU to NIE timer!
    }, 100);
  },
  startDobryThis() {
    setTimeout(() => {
      this.sekundy++; // arrow -> this === timer (dziedziczone z startDobryThis)
      console.log("sekundy:", this.sekundy);
    }, 100);
  },
};

timer.startDobryThis(); // "sekundy: 1" po 100ms - POPRAWNIE

const konto = {
  name: "Konto oszczednosciowe",
  opisz: () => {
    console.log(this.name); // BLEDNIE: undefined - this NIE jest konto!
  },
};

const konto = {
  name: "Konto oszczednosciowe",
  opisz() {
    console.log(this.name); // POPRAWNIE: "Konto oszczednosciowe" - this === konto
  },
};

konto.opisz();

