const ptak = { imie: "Kiwi", odezwijSieArrow: () => console.log(this) };

ptak.odezwijSieArrow();
// this jest undefined (w module ES) - arrow function NIE ma wlasnego this,
// wiec dziedziczy je z zewnetrznego, otaczajacego zasiegu (poziom modulu),
// a NIE z obiektu ptak, mimo ze jest jego "metoda".

const zegar = {
  godzina: 0,
  startArrow() {
    setTimeout(() => {
      this.godzina++;
      console.log(this.godzina);
    }, 10);
  },
};

zegar.startArrow(); // po 10ms wypisze 1 - this poprawnie === zegar

const zegar2 = {
  godzina: 0,
  startZwykla() {
    setTimeout(function () {
      // this.godzina++; -- BY NIE ZADZIALALO
    }, 10);
  },
};

zegar2.startZwykla();
// Zwykla funkcja (nie arrow) przekazana jako callback do setTimeout MA
// WLASNE this, ktore NIE jest zwiazane z zegar2 - setTimeout wywoluje ja
// samodzielnie, wiec this wewnatrz bylby undefined, a this.godzina++
// rzucilby blad proby odczytu wlasciwosci z undefined.

const gracz = {
  punkty: 0,
  dodajPunktyPoCzasie() {
    setTimeout(() => {
      this.punkty += 10;
      console.log(this.punkty);
    }, 5);
  },
};

gracz.dodajPunktyPoCzasie(); // po 5ms wypisze 10

const magazyn = {
