try {
  new Punkt();
} catch (e) {
  console.log(e.name); // -> "TypeError"
}
// Strzalka nie ma this ani prototype, wiec new jest niedozwolone.

const panel = {
  widoczny: false,
  przelaczPoCzasie() {
    setTimeout(() => {
      this.widoczny = !this.widoczny;
      console.log(this.widoczny);
    }, 5);
  }
