panel.przelaczPoCzasie(); // po 5 ms -> true

const zewn = {
  n: "zewn",
  f() {
    const wew = {
      n: "wew",
      a: () => this.n,
      b() {
        return this.n;
      }
    };
    return [wew.a(), wew.b()];
  }
};

console.log(zewn.f()); // -> ["zewn", "wew"]

"use strict";

const o = {
  m() {
    const zwykla = (function () { return this === undefined; })();
    const strzalka = (() => this === o)();
    return [zwykla, strzalka];
  }
};

console.log(o.m()); // -> [true, true]

