setTimeout(() => console.log(kolejka.zadania), 20); // -> ["a", "b"]

console.log(typeof (() => {}).prototype);        // -> "undefined"
console.log(typeof (function () {}).prototype);  // -> "object"
// Strzalki nie maja prototype, wiec nie mozna ich uzywac jako konstruktorow (new).

const licznik = {
  n: 0,
  dodaj(liczby) {                 // zwykla metoda - potrzebuje wlasnego this (obiektu licznik)
